#include <iostream>
#include <vector>
#include <array>
#include <memory>

struct Item {
    int id;
    Item(int val) : id(val) {}
    ~Item() { std::cout << "Item " << id << " deleted\n"; }
};

int main() {
    // 1. Giai phong bo nho an toan nho unique_ptr
    std::vector<std::unique_ptr<Item>> items;
    items.push_back(std::make_unique<Item>(10));
    items.push_back(std::make_unique<Item>(20));

    std::cout << "Calling erase on first element:\n";
    items.erase(items.begin()); // Item 10 bi huy ngay lap tuc

    std::cout << "Calling clear:\n";
    items.clear(); // Item 20 bi huy khi clear

    // 2. Minh hoa Range Insert va clear tren vector gia tri
    std::array<int, 4> source = { 2, 6, 4, 8 };
    std::vector<int> target = { 100, 200 };

    // Chen toan bo dai source vao vi tri giua 100 va 200
    auto it = target.insert(target.begin() + 1, source.cbegin(), source.cend());
    std::cout << "First inserted element: " << *it << "\n";
    std::cout << "Target elements: ";
    for (int val : target) {
        std::cout << val << ' ';
    }
    std::cout << "\nSize before clear: " << target.size() << "\n";

    target.clear();
    std::cout << "Size after clear: " << target.size() << "\n";

    return 0;
}

#include <iostream>
#include <list>

int main() {
    std::list<int> values;

    // Them phan tu o dau va cuoi
    values.push_front(1); // [1]
    values.push_front(2); // [2, 1]
    values.push_back(4);  // [2, 1, 4]
    values.push_back(3);  // [2, 1, 4, 3]

    std::cout << "Forward traversal: ";
    for (auto it = values.cbegin(); it != values.cend(); ++it) {
        std::cout << *it << ' ';
    }

    std::cout << "\nBackward traversal: ";
    for (auto it = values.crbegin(); it != values.crend(); ++it) {
        std::cout << *it << ' ';
    }

    values.pop_front(); // Xoa phan tu dau tien (2)
    values.pop_back();  // Xoa phan tu cuoi cung (3)

    std::cout << "\nAfter pop_front and pop_back: ";
    for (int val : values) {
        std::cout << val << ' ';
    }
    std::cout << "\n";

    return 0;
}

#include <iostream>
#include <list>
#include <algorithm>
#include <iterator>

template <typename T>
void printList(const std::list<T>& listRef) {
    if (listRef.empty()) {
        std::cout << "List is empty";
    } else {
        std::ostream_iterator<T> output(std::cout, " ");
        std::copy(listRef.cbegin(), listRef.cend(), output);
    }
    std::cout << "\n";
}

int main() {
    std::list<int> values = { 2, 1, 4, 3 };
    std::list<int> otherValues = { 2, 6, 4, 8 };

    // 1. sort
    values.sort();
    std::cout << "values after sorting: ";
    printList(values);

    // 2. splice toan bo otherValues vao cuoi values
    values.splice(values.cend(), otherValues);
    std::cout << "values after splice: ";
    printList(values);
    std::cout << "otherValues after splice: ";
    printList(otherValues);

    // 3. Sap xep va unique
    values.sort();
    values.unique();
    std::cout << "values after sort and unique: ";
    printList(values);

    // 4. remove: loai bo moi phan tu co gia tri 4
    values.remove_if([](int value){return value == 4;});
    std::cout << "values after remove(4): ";
    printList(values);

    // 5. merge hai danh sach da sap xep
    otherValues.assign({ 2, 5, 7 });
    values.merge(otherValues);
    std::cout << "values after merge: ";
    printList(values);
    std::cout << "otherValues after merge: ";
    printList(otherValues);

    return 0;
}
